"""Deterministic Markdown reporting for prompt-refinement comparisons."""

from __future__ import annotations

from prompt_refinement_eval.analysis import AnalysisReport


def render_markdown(report: AnalysisReport) -> str:
    """Render an evidence-led report without claiming unsupported improvement."""

    lines = [
        "<!-- Generated by prompt-refinement-eval; do not hand-edit totals. -->",
        "# Historical prompt-refinement results",
        "",
        "## Finding",
        "",
        _finding(report),
        "",
        "## Observed results",
        "",
        (
            "These rates use each arm's available historical tasks and therefore have different "
            "denominators. They are descriptive, not a fair causal comparison."
        ),
        "",
        "| Arm | Accepted | Observed | Acceptance | Missing from union |",
        "| --- | ---: | ---: | ---: | ---: |",
    ]
    for arm_summary in report.arms:
        lines.append(
            "| "
            f"{_cell(_arm_label(arm_summary.name))} | {arm_summary.accepted} | "
            f"{arm_summary.observed_total} | {_percentage(arm_summary.acceptance_rate)} | "
            f"{len(arm_summary.missing_ids)} |"
        )

    lines.extend(
        [
            "",
            "## Complete-case comparison",
            "",
            (
                "All arms share "
                f"{len(report.complete_cases.task_ids)} tasks. Restricting every arm to this "
                "same intersection gives:"
            ),
            "",
            "| Arm | Accepted | Shared tasks | Acceptance |",
            "| --- | ---: | ---: | ---: |",
        ]
    )
    for complete_arm in report.complete_cases.arms:
        lines.append(
            f"| {_cell(_arm_label(complete_arm.name))} | {complete_arm.accepted} | "
            f"{complete_arm.accepted + complete_arm.failed} | "
            f"{_percentage(complete_arm.acceptance_rate)} |"
        )

    lines.extend(
        [
            "",
            "## Paired comparisons",
            "",
            (
                "Differences are arm B minus arm A on their exact ID intersection. The p-value is "
                "the two-sided exact McNemar test over discordant correctness outcomes."
            ),
            "",
            "| Arm A | Arm B | Paired n | A only | B only | Difference | Exact p |",
            "| --- | --- | ---: | ---: | ---: | ---: | ---: |",
        ]
    )
    for comparison in report.pairwise:
        lines.append(
            "| "
            f"{_cell(_arm_label(comparison.arm_a))} | "
            f"{_cell(_arm_label(comparison.arm_b))} | "
            f"{comparison.paired_count} | {comparison.a_only_accepted} | "
            f"{comparison.b_only_accepted} | "
            f"{_percentage_points(comparison.acceptance_rate_difference_b_minus_a)} | "
            f"{_p_value(comparison.mcnemar_exact_p_value)} |"
        )

    if report.benchmark_audit is not None:
        audit = report.benchmark_audit
        status = (
            f"valid with {audit.warning_count} warnings"
            if audit.is_valid
            else f"invalid with {audit.error_count} errors and {audit.warning_count} warnings"
        )
        lines.extend(
            [
                "",
                "## Benchmark audit and sensitivity",
                "",
                (
                    f"The {audit.record_count}-task benchmark is structurally {status}. "
                    f"Its content fingerprint is `{audit.sha256}`."
                ),
                "",
                f"Validation-summary fingerprint: `{audit.validation_summary_sha256}`",
            ]
        )
        if audit.correction_manifest_source and audit.correction_manifest_sha256:
            lines.extend(
                [
                    "",
                    (
                        "Correction manifest newline-canonical content fingerprint: "
                        f"`{_cell(audit.correction_manifest_source)}` "
                        f"(`{audit.correction_manifest_sha256}`)"
                    ),
                ]
            )
        if report.benchmark_alignment is not None:
            alignment = report.benchmark_alignment
            if not alignment.benchmark_only_ids and not alignment.result_only_ids:
                lines.extend(
                    [
                        "",
                        "The benchmark IDs exactly match the union of recorded result IDs.",
                    ]
                )
            elif alignment.benchmark_only_ids:
                missing = ", ".join(map(str, alignment.benchmark_only_ids))
                lines.extend(
                    [
                        "",
                        f"Benchmark IDs absent from every result arm: {missing}.",
                    ]
                )
        if report.sensitivity is not None:
            excluded = ", ".join(map(str, report.sensitivity.excluded_task_ids))
            lines.extend(
                [
                    "",
                    (
                        "A sensitivity analysis excludes the task-identity conflicts flagged "
                        f"by validation (IDs {excluded}). The paired conclusion is unchanged:"
                    ),
                    "",
                    (
                        f"All arms share {len(report.sensitivity.complete_case_ids)} tasks after "
                        "those exclusions."
                    ),
                    "",
                    "| Arm | Accepted | Shared tasks | Acceptance |",
                    "| --- | ---: | ---: | ---: |",
                ]
            )
            for complete_arm in report.sensitivity.complete_case_arms:
                lines.append(
                    f"| {_cell(_arm_label(complete_arm.name))} | {complete_arm.accepted} | "
                    f"{complete_arm.accepted + complete_arm.failed} | "
                    f"{_percentage(complete_arm.acceptance_rate)} |"
                )
            lines.extend(
                [
                    "",
                    "| Arm A | Arm B | Paired n | A only | B only | Difference | Exact p |",
                    "| --- | --- | ---: | ---: | ---: | ---: | ---: |",
                ]
            )
            for comparison in report.sensitivity.pairwise:
                lines.append(
                    "| "
                    f"{_cell(_arm_label(comparison.arm_a))} | "
                    f"{_cell(_arm_label(comparison.arm_b))} | "
                    f"{comparison.paired_count} | {comparison.a_only_accepted} | "
                    f"{comparison.b_only_accepted} | "
                    f"{_percentage_points(comparison.acceptance_rate_difference_b_minus_a)} | "
                    f"{_p_value(comparison.mcnemar_exact_p_value)} |"
                )

    if report.overlap_risk_audit is not None and report.overlap_risk_sensitivity is not None:
        overlap_audit = report.overlap_risk_audit
        overlap_sensitivity = report.overlap_risk_sensitivity
        excluded = ", ".join(map(str, overlap_sensitivity.excluded_task_ids))
        lines.extend(
            [
                "",
                "## Training/benchmark overlap risk",
                "",
                (
                    "A hash-bound review confirms equivalent task variants in the retained "
                    f"training export for benchmark IDs {excluded}. The exact binding between "
                    "that export and the evaluated fine-tuned model is not recorded, so this "
                    "is a leakage-risk sensitivity—not proof of model contamination."
                ),
                "",
                (
                    "Overlap manifest newline-canonical content fingerprint: "
                    f"`{_cell(overlap_audit.source)}` "
                    f"(`{overlap_audit.manifest_sha256}`)"
                ),
                "",
                (
                    f"All arms share {len(overlap_sensitivity.complete_case_ids)} tasks after "
                    "excluding the confirmed variants."
                ),
                "",
                "| Arm | Accepted | Shared tasks | Acceptance |",
                "| --- | ---: | ---: | ---: |",
            ]
        )
        for complete_arm in overlap_sensitivity.complete_case_arms:
            lines.append(
                f"| {_cell(_arm_label(complete_arm.name))} | {complete_arm.accepted} | "
                f"{complete_arm.accepted + complete_arm.failed} | "
                f"{_percentage(complete_arm.acceptance_rate)} |"
            )
        lines.extend(
            [
                "",
                "| Arm A | Arm B | Paired n | A only | B only | Difference | Exact p |",
                "| --- | --- | ---: | ---: | ---: | ---: | ---: |",
            ]
        )
        for comparison in overlap_sensitivity.pairwise:
            lines.append(
                "| "
                f"{_cell(_arm_label(comparison.arm_a))} | "
                f"{_cell(_arm_label(comparison.arm_b))} | "
                f"{comparison.paired_count} | {comparison.a_only_accepted} | "
                f"{comparison.b_only_accepted} | "
                f"{_percentage_points(comparison.acceptance_rate_difference_b_minus_a)} | "
                f"{_p_value(comparison.mcnemar_exact_p_value)} |"
            )

    lines.extend(
        [
            "",
            "## Provenance",
            "",
            f"Task-union fingerprint: `{report.task_union_sha256}`",
            "",
            "| Arm | Source | Canonical text SHA-256 | Observed judge window (UTC) |",
            "| --- | --- | --- | --- |",
        ]
    )
    for provenance_arm in report.arms:
        run_window = _run_window(
            provenance_arm.observed_run_started_at,
            provenance_arm.observed_run_ended_at,
        )
        lines.append(
            f"| {_cell(_arm_label(provenance_arm.name))} | "
            f"`{_cell(provenance_arm.source)}` | "
            f"`{provenance_arm.source_sha256}` | {_cell(run_window)} |"
        )

    lines.extend(
        [
            "",
            (
                "Derived run IDs bind these labels to the source fingerprints above. Model "
                "names are historical labels; the artifacts do not record exact provider "
                "snapshots or inference parameters."
            ),
            (
                "Canonical text fingerprints remove an optional UTF-8 BOM and normalize CRLF "
                "or CR newlines to LF before SHA-256; no other content is transformed."
            ),
            "",
            (
                "| Arm | Derived run ID | Strategy | Historical generator | "
                "Historical refiner | Exact snapshot / parameters |"
            ),
            "| --- | --- | --- | --- | --- | --- |",
        ]
    )
    for provenance_arm in report.arms:
        archival_run = provenance_arm.archival_run
        refiner_label = (
            "none (direct generation)"
            if archival_run.refiner_label is None
            else archival_run.refiner_label
        )
        lines.append(
            f"| {_cell(_arm_label(provenance_arm.name))} | "
            f"`{archival_run.run_id}` | {_cell(archival_run.strategy)} | "
            f"{_cell(archival_run.generator_label)} | {_cell(refiner_label)} | "
            "not recorded / not recorded |"
        )

    lines.extend(
        [
            "",
            "## Limitations",
            "",
            "- These are historical judge observations, not a newly rerun experiment.",
            (
                "- Historical labels are not bound to exact provider snapshots, inference "
                "parameters, or training-artifact hashes."
            ),
            "- Model generations were not repeated across random seeds.",
            "- Some arms are missing tasks; paired and complete-case counts are shown explicitly.",
            "- Exact p-values are descriptive and are not adjusted for multiple comparisons.",
            (
                "- Correctness on coding tasks does not measure maintainability, security, "
                "or usability."
            ),
        ]
    )
    if report.sensitivity is not None:
        lines.append(
            "- Likely task-identity conflicts remain in the headline history; the sensitivity "
            "analysis excludes them."
        )
    if report.issues:
        lines.extend(["", "## Data integrity notes", ""])
        for issue in report.issues:
            lines.append(f"- `{_cell(issue.arm)}` / `{issue.code}`: {_cell(issue.message)}")
    return "\n".join(lines).rstrip() + "\n"


def _finding(report: AnalysisReport) -> str:
    baseline = next((arm for arm in report.arms if arm.name == "baseline_gpt35"), None)
    refined = [arm for arm in report.arms if arm.name != "baseline_gpt35"]
    if baseline is None or not refined:
        return (
            "The supplied arms require paired interpretation; separate headline rates alone do "
            "not demonstrate that refinement improves correctness."
        )

    baseline_complete = next(
        (item for item in report.complete_cases.arms if item.name == baseline.name), None
    )
    if baseline_complete is None or baseline_complete.acceptance_rate is None:
        return (
            "The supplied arms require paired interpretation; separate headline rates alone do "
            "not demonstrate that prompt refinement improves correctness."
        )
    baseline_rate = baseline_complete.acceptance_rate
    higher_refined = [
        item
        for item in report.complete_cases.arms
        if item.name != baseline.name
        and item.acceptance_rate is not None
        and item.acceptance_rate > baseline_rate
    ]
    if not higher_refined:
        return (
            "The historical evidence does not demonstrate an improvement from prompt refinement. "
            "On the shared task set, direct generation has the highest acceptance rate."
        )
    return (
        "At least one refined arm has a higher descriptive complete-case rate, but an improvement "
        "claim still requires the paired effect and uncertainty reported below."
    )


def _percentage(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:.2f}%"


def _percentage_points(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:+.2f} pp"


def _p_value(value: float) -> str:
    return f"{value:.2e}" if 0 < value < 0.0001 else f"{value:.4f}"


def _run_window(started_at: str | None, ended_at: str | None) -> str:
    if started_at is None or ended_at is None:
        return "not recorded"
    return f"{started_at} to {ended_at}"


def _arm_label(name: str) -> str:
    labels = {
        "baseline_gpt35": "Direct generation (GPT-3.5)",
        "finetuned_refiner_gpt35": "Fine-tuned refiner -> GPT-3.5",
        "gpt4o_refiner_gpt35": "GPT-4o refiner -> GPT-3.5",
    }
    return labels.get(name, name)


def _cell(value: object) -> str:
    return str(value).replace("|", "\\|").replace("\n", " ")
